{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfbfc;--card:#fff;--muted:#6b7280;--accent:#0f766e;--accent-2:#9f7aea;--glass:rgba(255,255,255,0.6)}
    html,body{height:100%;margin:0;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial;color:#0b1220;background:linear-gradient(180deg,var(--bg),#f4f7f9)}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 28px}
    .brand{display:flex;align-items:center;gap:12px}
    .logo-sq{width:44px;height:44px;border-radius:8px;background:linear-gradient(135deg,var(--accent),var(--accent-2));display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700}
    nav a{margin:0 10px;color:var(--muted);text-decoration:none;font-weight:600}
    .container{max-width:1100px;margin:18px auto;padding:0 20px}
    .hero{display:grid;grid-template-columns:1fr 360px;gap:28px;align-items:center}
    .panel{background:var(--card);border-radius:12px;padding:28px;box-shadow:0 6px 20px rgba(16,24,40,0.06)}
    h1{margin:0 0 8px;font-size:28px;letter-spacing:-0.02em}
    p.lead{margin:0;color:var(--muted);line-height:1.5}
    .svg-wrap{position:relative;height:220px;border-radius:12px;overflow:hidden}
    .pattern-svg{position:absolute;inset:0;width:100%;height:100%}
    .mood{display:flex;gap:10px;margin-top:16px}
    .mood button{flex:1;padding:10px;border-radius:8px;border:1px solid #e6eef0;background:transparent;font-weight:600;color:#073642;cursor:pointer}
    .mood button.active{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#fff;border:none;box-shadow:0 6px 18px rgba(15,118,110,0.12)}
    .approach{margin-top:18px;padding:14px;border-radius:8px;background:linear-gradient(180deg,rgba(159,122,234,0.06),rgba(15,118,110,0.03))}
    .cta{display:inline-flex;align-items:center;gap:10px;padding:12px 16px;border-radius:10px;background:var(--accent);color:#fff;text-decoration:none;font-weight:700}
    .meta{font-size:13px;color:var(--muted);margin-top:12px}
    .grid-2{display:grid;grid-template-columns:repeat(2,1fr);gap:14px;margin-top:20px}
    .card{padding:14px;border-radius:10px;background:linear-gradient(180deg,#fff,#fbfeff);border:1px solid rgba(12,31,33,0.04)}
    footer{margin:40px 0 80px;text-align:center;color:var(--muted)}
    @media (max-width:900px){.hero{grid-template-columns:1fr;border-radius:0}.svg-wrap{height:160px}.grid-2{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo-sq">WC</div>
      <div>
        <div style="font-weight:800">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="about.html">Who I Am</a>
      <a href="services.html">Offerings</a>
      <a href="programs.html">Programs</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main class="container">
    <section class="hero">
      <div class="panel">
        <h1>Clarity for your day-to-day practice</h1>
        <p class="lead">I design simple routines and small commitments that change how you move through work and home — outcomes, not tests. My work is built for people who need practical systems that actually fit their life.</p>

        <div class="mood" role="tablist" aria-label="Mood to method selector">
          <button data-key="overwhelmed" class="active">Overwhelmed</button>
          <button data-key="flat">Flat</button>
          <button data-key="energized">Energized</button>
          <button data-key="curious">Curious</button>
        </div>

        <div class="approach" id="approach">
          <strong>Recommended approach:</strong>
          <div id="approachText">A concise VIP Day to map your current demands and leave with a 7-step rhythm for steady mornings and calm transitions.</div>
          <div class="meta">Includes session notes, a clear daily checklist, and one 30-minute follow-up.</div>
        </div>

        <div style="margin-top:16px">
          <a id="primaryCta" class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <span style="margin-left:12px;color:var(--muted);font-weight:600">or call <a href="tel:{{PHONE}}" style="color:var(--accent);text-decoration:none">{{PHONE}}</a></span>
        </div>

        <div class="grid-2">
          <div class="card"><strong>What you can expect</strong><div style="color:var(--muted);margin-top:8px">Concrete habit anchors, a one-page weekly layout, and time-capped practices to protect energy.</div></div>
          <div class="card"><strong>Who it’s for</strong><div style="color:var(--muted);margin-top:8px">Professionals balancing demanding work, caregiving, or both — people who want frameworks not fads.</div></div>
        </div>
      </div>

      <aside class="svg-wrap panel" aria-hidden="true">
        <!-- Unique decorative SVG pattern (inline, not external) -->
        <svg class="pattern-svg" viewBox="0 0 600 380" preserveAspectRatio="none" xmlns="http://www.w3.org/2000/svg">
          <defs>
            <linearGradient id="g1" x1="0" x2="1">
              <stop offset="0" stop-color="#e6fffa" />
              <stop offset="1" stop-color="#f5f3ff" />
            </linearGradient>
            <pattern id="p1" width="40" height="40" patternUnits="userSpaceOnUse">
              <rect width="40" height="40" fill="rgba(255,255,255,0)" />
              <path d="M0 30 L20 0 L40 30" stroke="#dff6f3" stroke-width="1.5" fill="none" />
            </pattern>
          </defs>
          <rect width="100%" height="100%" fill="url(#g1)" />
          <rect width="100%" height="100%" fill="url(#p1)" opacity="0.9" />
          <g transform="translate(60,220) rotate(-12)" opacity="0.9">
            <rect x="0" y="0" width="160" height="100" rx="12" fill="#ffffff" opacity="0.6" />
            <circle cx="32" cy="50" r="26" fill="#9f7aea" opacity="0.12" />
            <circle cx="120" cy="30" r="18" fill="#0f766e" opacity="0.08" />
          </g>
        </svg>
      </aside>
    </section>

    <section style="margin-top:20px" class="panel">
      <h3 style="margin:0 0 8px">How I work — a short note</h3>
      <p style="color:var(--muted);margin:0">I focus on three outcomes: fewer decision moments, reliable micro-habits, and a weekly pattern you can actually keep. That means we measure time, not willpower, and design practice around your real constraints.</p>
    </section>

    <section style="margin-top:18px;display:flex;gap:14px;flex-wrap:wrap">
      <div class="panel" style="flex:1;min-width:260px">
        <h4 style="margin:0 0 6px">Short VIP Day</h4>
        <p style="color:var(--muted);margin:0">A focused design day to map a workable rhythm and leave with a prioritized sequence of micro-commitments.</p>
      </div>

      <div class="panel" style="flex:1;min-width:260px">
        <h4 style="margin:0 0 6px">Weekly Tune-up</h4>
        <p style="color:var(--muted);margin:0">A 60-minute session to recalibrate commitments, swap tactics, and strengthen habits in a single pass.</p>
      </div>
    </section>

    <section style="margin-top:18px" class="panel">
      <h4 style="margin:0 0 8px">Questions people ask</h4>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px">
        <div style="padding:10px;border-radius:8px;background:#fff">Will this fit my week?<div style="color:var(--muted);margin-top:8px">Yes—plans are scaled to your rhythms and time blocks you already use.</div></div>
        <div style="padding:10px;border-radius:8px;background:#fff">Is this clinical care?<div style="color:var(--muted);margin-top:8px">No. This is coaching focused on habits, routines, and accountability frameworks.</div></div>
      </div>
    </section>

  </main>

  <footer>
    <div style="font-weight:700">Ready to turn a restless week into a focused one?</div>
    <div style="margin-top:8px;color:var(--muted)"><a href="{{PRIMARY_CTA_URL}}" style="color:var(--accent);text-decoration:none;font-weight:700">{{PRIMARY_CTA_LABEL}}</a> — or email <a href="mailto:{{EMAIL}}" style="color:var(--accent);text-decoration:none">{{EMAIL}}</a></div>
    <div style="margin-top:14px;color:var(--muted);font-size:13px">Serving {{CITY}}, {{STATE}} • <a href="tel:{{PHONE}}" style="color:var(--muted);text-decoration:none">{{PHONE}}</a></div>
  </footer>

  <script>
    // Mood-to-Method: updates recommended approach and CTA subtly
    (function(){
      const mapping = {
        overwhelmed: {
          title: 'A single-day reset',
          text: 'A VIP Day focused on clearing friction: we map critical drains and establish a short daily sequence to protect attention and energy.',
          ctaSuffix: ' — Start the Day'
        },
        flat: {
          title: 'Small wins rhythm',
          text: 'A two-session arc to introduce micro-practices and a compact weekly layout that lifts baseline energy without extra appointments.',
          ctaSuffix: ' — Raise the Baseline'
        },
        energized: {
          title: 'Amplify what works',
          text: 'We channel existing momentum into sustainable habits and protect pockets of time so gains stick beyond the short term.',
          ctaSuffix: ' — Amplify Momentum'
        },
        curious: {
          title: 'Experiment & lock',
          text: 'A modular series to test lightweight practices and lock the ones that deliver consistent returns for your life and work.',
          ctaSuffix: ' — Try a Module'
        }
      };

      const buttons = document.querySelectorAll('.mood button');
      const approachText = document.getElementById('approachText');
      const primary = document.getElementById('primaryCta');
      buttons.forEach(btn=>btn.addEventListener('click',function(){
        buttons.forEach(b=>b.classList.remove('active'));
        this.classList.add('active');
        const key = this.dataset.key;
        const m = mapping[key];
        approachText.innerHTML = '<strong>'+m.title+':</strong> '+m.text;
        // animate CTA text change
        const base = '{{PRIMARY_CTA_LABEL}}';
        primary.textContent = base + m.ctaSuffix;
        // gentle emphasis pulse
        primary.animate([{transform:'scale(1)'},{transform:'scale(1.02)'},{transform:'scale(1)'}],{duration:420,iterations:1});
      }));
    })();
  </script>
</body>
</html>"} 
{"path":"services.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Offerings — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f8fafb;--card:#ffffff;--muted:#5b6b73;--accent:#0f766e;--accent-2:#f59e0b}
    body{margin:0;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, Arial;color:#062022;background:var(--bg)}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 26px}
    .logo{font-weight:800}
    nav a{margin:0 8px;color:var(--muted);text-decoration:none;font-weight:600}
    .wrap{max-width:1100px;margin:18px auto;padding:0 20px}
    .top{display:flex;gap:20px;align-items:center}
    .title{flex:1}
    h1{margin:0;font-size:26px}
    p.sub{margin:6px 0 0;color:var(--muted)}
    .grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:18px}
    .plan{background:var(--card);padding:18px;border-radius:12px;box-shadow:0 8px 24px rgba(7,24,24,0.04);position:relative}
    .plan h3{margin:0 0 8px}
    .price{font-size:22px;font-weight:800;color:var(--accent);display:flex;align-items:baseline;gap:8px}
    .muted{color:var(--muted)}
    .toggle{display:inline-flex;background:#fff;border-radius:999px;padding:6px;border:1px solid rgba(2,6,23,0.06)}
    .toggle button{border:0;background:transparent;padding:8px 12px;border-radius:999px;font-weight:700;cursor:pointer}
    .toggle button.active{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#fff}
    .compare{display:flex;align-items:center;gap:14px}
    .foot{margin-top:20px;color:var(--muted);font-size:13px}
    @media (max-width:1000px){.grid{grid-template-columns:1fr} .top{flex-direction:column;align-items:flex-start}}
  </style>
</head>
<body>
  <header>
    <div class="logo">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="index.html">Home</a>
      <a href="services.html">Offerings</a>
      <a href="programs.html">Programs</a>
      <a href="pricing.html">Investments</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main class="wrap">
    <div class="top">
      <div class="title">
        <h1>Offerings framed around outcomes</h1>
        <p class="sub">Pick the cadence that fits you. Services below show monthly retainer cost and an alternative packaged investment for short intensives.</p>
      </div>

      <div class="compare">
        <div style="font-size:13px;color:var(--muted);font-weight:700">Price view</div>
        <div class="toggle" role="tablist" aria-label="Pricing view">
          <button id="viewMonthly" class="active">Monthly</button>
          <button id="viewPackage">Package</button>
        </div>
      </div>
    </div>

    <section class="grid" aria-live="polite">
      <article class="plan" data-month="550" data-package="1800">
        <h3>Focused Habit Kit</h3>
        <div class="price"><span class="amount">$550</span><span class="muted">/month</span></div>
        <p class="muted">Weekly check-ins, a 6-week habit pathway, and template tools to embed new routines into your days.</p>
        <div style="margin-top:12px"><a class="book" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a></div>
      </article>

      <article class="plan" data-month="850" data-package="2800">
        <h3>Weekly Structure Lab</h3>
        <div class="price"><span class="amount">$850</span><span class="muted">/month</span></div>
        <p class="muted">A practical restructuring of your week with task batching, energy windows, and checklists to limit decision fatigue.</p>
        <div style="margin-top:12px"><a class="book" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a></div>
      </article>

      <article class="plan" data-month="200" data-package="700">
        <h3>One-Off VIP Day</h3>
        <div class="price"><span class="amount">$200</span><span class="muted">/month</span></div>
        <p class="muted">A concentrated design session to emerge with a lean schedule and a checklist you can use on Monday morning.</p>
        <div style="margin-top:12px"><a class="book" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a></div>
      </article>
    </section>

    <div class="foot">Notes: Monthly figures reflect standard coaching cadence. Package prices are a single investment for a defined engagement. No clinical claims — outcomes, routines, and accountability only.</div>
  </main>

  <script>
    // Pricing Comparator: toggles and animates numbers
    (function(){
      const btnMonthly = document.getElementById('viewMonthly');
      const btnPackage = document.getElementById('viewPackage');
      const plans = Array.from(document.querySelectorAll('.plan'));
      let mode = 'month';

      function animateTo(el, from, to, suffix){
        const duration = 450;
        const start = performance.now();
        function frame(now){
          const t = Math.min(1,(now-start)/duration);
          const v = Math.round(from + (to-from) * (1 - Math.pow(1-t,3)) );
          el.textContent = '$' + v;
          if(t<1) requestAnimationFrame(frame);
          else el.textContent = '$' + to;
        }
        requestAnimationFrame(frame);
      }

      function update(toMode){
        mode = toMode;
        plans.forEach(plan=>{
          const amtEl = plan.querySelector('.amount');
          const from = parseInt(amtEl.textContent.replace('$','')) || 0;
          const to = parseInt(plan.dataset[toMode==='month'?'month':'package']);
          const mut = plan.querySelector('.muted');
          mut.textContent = toMode==='month'?'/month':'/package';
          animateTo(amtEl, from, to, mut.textContent);
        });
      }

      btnMonthly.addEventListener('click',function(){
        if(this.classList.contains('active')) return;
        btnMonthly.classList.add('active');btnPackage.classList.remove('active');
        update('month');
      });
      btnPackage.addEventListener('click',function(){
        if(this.classList.contains('active')) return;
        btnPackage.classList.add('active');btnMonthly.classList.remove('active');
        update('package');
      });

      // initial values ensure animation consistent
      plans.forEach(p=>{
        const start = parseInt(p.dataset.month);
        p.querySelector('.amount').textContent = '$' + start;
      });
    })();
  </script>
</body>
</html>"} 
{"path":"programs.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Programs — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fff;--muted:#5b6b73;--accent:#0f766e;--card:#fff}
    body{margin:0;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, Arial;background:linear-gradient(180deg,#fbfdfe,#fff)}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 26px}
    nav a{margin:0 8px;color:var(--muted);text-decoration:none}
    .wrap{max-width:1100px;margin:18px auto;padding:0 20px}
    .lead{display:flex;gap:20px;align-items:flex-start}
    .col{background:var(--card);padding:18px;border-radius:12px;box-shadow:0 8px 24px rgba(2,6,23,0.04)}
    .col.small{width:320px}
    h1{margin:0}
    p{color:var(--muted)}
    .methods{display:grid;grid-template-columns:repeat(2,1fr);gap:14px;margin-top:14px}
    .method{padding:12px;border-radius:10px;background:linear-gradient(180deg,#fbfeff,#ffffff);border:1px solid rgba(2,6,23,0.04)}
    .mood-sel{display:flex;gap:8px;margin-top:12px}
    .mood-sel button{padding:8px 10px;border-radius:999px;border:1px solid #e6eef0;background:#fff;cursor:pointer}
    .mood-sel button.active{background:linear-gradient(90deg,var(--accent),#9f7aea);color:#fff}
    .cta{display:inline-block;margin-top:12px;padding:10px 14px;background:var(--accent);color:#fff;border-radius:10px;text-decoration:none;font-weight:700}
    .pricing-row{display:flex;gap:12px;align-items:center;margin-top:12px}
    .mini-toggle{display:inline-flex;border-radius:999px;background:#fff;padding:4px;border:1px solid rgba(2,6,23,0.06)}
    .mini-toggle button{padding:6px 8px;border-radius:999px;border:0;background:transparent;cursor:pointer;font-weight:700}
    .mini-toggle button.active{background:#0f766e;color:#fff}
    @media (max-width:900px){.lead{flex-direction:column}.methods{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div style="font-weight:800">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="index.html">Start</a>
      <a href="about.html">Who</a>
      <a href="services.html">Offerings</a>
      <a href="programs.html">Programs</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main class="wrap">
    <div class="lead">
      <div class="col" style="flex:1">
        <h1>Programs you can test in a week</h1>
        <p>Short pathways that prioritize a single measurable shift: fewer decisions, steadier focus, or cleaner transitions between work and life.</p>

        <div style="margin-top:12px">
          <div class="mood-sel" role="tablist">
            <button data-key="slow" class="active">Running behind</button>
            <button data-key="drained">Drained</button>
            <button data-key="tooBusy">Too busy</button>
            <button data-key="ready">Ready to scale</button>
          </div>
        </div>

        <div style="margin-top:14px">
          <div id="methodPanel" class="methods">
            <div class="method"><strong id="methodTitle">Micro Reset</strong><div id="methodDesc" style="color:var(--muted);margin-top:8px">A focused 1-hour plan to triage tasks, set three anchors for your day, and block recovery time.</div></div>
            <div class="method"><strong>Deliverables</strong><div style="color:var(--muted);margin-top:8px">One-page daily template, specific micro-habits, and a 15-minute follow-up script.</div></div>
          </div>

          <a id="programCta" class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        </div>
      </div>

      <aside class="col small">
        <h4 style="margin:0 0 6px">Price quick view</h4>
        <div class="pricing-row">
          <div class="mini-toggle" role="tablist">
            <button id="pMonthly" class="active">Monthly</button>
            <button id="pPack">Pack</button>
          </div>
          <div style="font-weight:800;font-size:18px" id="priceDisplay">$200</div>
        </div>

        <div style="margin-top:12px;color:var(--muted)">Adjusts based on selected method.</div>

        <div style="margin-top:16px">
          <strong>Quick facts</strong>
          <ul style="color:var(--muted);padding-left:18px;margin:8px 0 0">
            <li>No medical claims — frameworks and habit design.</li>
            <li>VIP Day available as a single-session investment.</li>
          </ul>
        </div>
      </aside>
    </div>

    <section style="margin-top:18px;display:grid;grid-template-columns:1fr 1fr;gap:14px">
      <div class="col">
        <h4 style="margin:0 0 8px">Programs — names that reflect your work</h4>
        <div style="display:flex;flex-direction:column;gap:10px">
          <div style="padding:10px;border-radius:8px;background:#fff">Micro Reset (single session) — $200 / $700</div>
          <div style="padding:10px;border-radius:8px;background:#fff">Steady Week (4 weeks) — $550 / $1800</div>
          <div style="padding:10px;border-radius:8px;background:#fff">Boundaries Lab (8 weeks) — $850 / $2800</div>
        </div>
      </div>

      <div class="col">
        <h4 style="margin:0 0 8px">Why choose a short path?</h4>
        <p style="color:var(--muted)">Short, focused engagements expose what works quickly and keep investment aligned with the specific outcome you care about. Each program focuses on concrete habit anchors and repeatable routines.</p>

        <div style="margin-top:12px"><a href="{{PRIMARY_CTA_URL}}" class="cta">{{PRIMARY_CTA_LABEL}}</a></div>
      </div>
    </section>

    <footer style="margin-top:22px;color:var(--muted)">Questions? Email <a href="mailto:{{EMAIL}}" style="color:var(--muted);text-decoration:none">{{EMAIL}}</a> or call <a href="tel:{{PHONE}}" style="color:var(--muted);text-decoration:none">{{PHONE}}</a>. Serving {{CITY}}, {{STATE}}.</footer>
  </main>

  <script>
    // Mood-to-Method selector updates method panel & CTA
    (function(){
      const mapping = {
        slow: {title:'Micro Reset', desc:'Triage and three anchors to rescue the day.', price:{month:200,pack:700}, ctaSuffix:' — Book Reset'},
        drained: {title:'Recovery Blocks', desc:'Time-boxed recovery rituals and energy-conserving practices.', price:{month:250,pack:800}, ctaSuffix:' — Start Recovery'},
        tooBusy: {title:'Week Design', desc:'A two-hour plan to batch work and defend focus windows.', price:{month:550,pack:1800}, ctaSuffix:' — Design the Week'},
        ready: {title:'Scale Habits', desc:'An 8-week module to scale systems and lock reliable outcomes.', price:{month:850,pack:2800}, ctaSuffix:' — Scale Now'}
