      const descEl = document.getElementById('methodDesc');
      const cta = document.getElementById('programCta');
      const priceDisplay = document.getElementById('priceDisplay');
      const pMonthly = document.getElementById('pMonthly');
      const pPack = document.getElementById('pPack');
      let priceMode = 'month';

      function setActive(key){
        buttons.forEach(b=>b.classList.toggle('active', b.dataset.key===key));
        const m = mapping[key];
        titleEl.textContent = m.title;
        descEl.textContent = m.desc;
        cta.textContent = '{{PRIMARY_CTA_LABEL}}' + m.ctaSuffix;
        updatePrice(m.price);
      }

      function updatePrice(priceObj){
        const value = priceMode==='month'?priceObj.month:priceObj.pack;
        // animate numeric change
        const start = parseInt(priceDisplay.textContent.replace('$','')) || 0;
        const end = value;
        const dur = 380;
        const s = performance.now();
        function tick(now){
          const t = Math.min(1,(now-s)/dur);
          const val = Math.round(start + (end-start) * t);
          priceDisplay.textContent = '$' + val;
          if(t<1) requestAnimationFrame(tick);
        }
        requestAnimationFrame(tick);
      }

      buttons.forEach(b=>b.addEventListener('click',function(){
        const key = this.dataset.key;
        setActive(key);
      }));

      pMonthly.addEventListener('click',function(){ priceMode='month'; pMonthly.classList.add('active'); pPack.classList.remove('active'); // refresh
