        const m = mapping[key]; updatePrice(m.price);
      });
      pPack.addEventListener('click',function(){ priceMode='pack'; pPack.classList.add('active'); pMonthly.classList.remove('active'); const key = Array.from(buttons).find(b=>b.classList.contains('active')).dataset.key; const m = mapping[key]; updatePrice(m.price); });

      // initial state
      setActive('slow');
    })();
